import sys
from decimal import Decimal, ROUND_HALF_UP

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 3:
            continue
        a_str, op, b_str = parts
        a = Decimal(a_str)
        b = Decimal(b_str)
        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        elif op == "*":
            result = a * b
        elif op == "/":
            if b == 0:
                print("ERROR")
                continue
            result = a / b
            result = result.quantize(Decimal('0.0000000000'), rounding=ROUND_HALF_UP)
        else:
            print("ERROR")
            continue
        if result == int(result):
            print(str(int(result)))
        elif result < 0:
            print(str(result))
        else:
            print(str(result).rstrip('0').rstrip('.'))
    return

if __name__ == "__main__":
    main()
